public List<TaskResponse> getAllTasksForCurrentUser(Optional<Long> categoryId) {
    User currentUser = getCurrentUser();
    if (categoryId.isPresent()) {
        // optional: verify category belongs to user
        return taskRepository.findByUserIdAndCategoryId(currentUser.getId(), categoryId.get())
                .stream().map(this::toResponse).collect(Collectors.toList());
    }
    return taskRepository.findByUserId(currentUser.getId())
            .stream().map(this::toResponse).collect(Collectors.toList());
}

